/*
 * Keystone embeddable chat widget (docs/embed-widget-plan.md §7).
 *
 * Hand-written vanilla JS, ES5-safe (no arrow functions, no let/const, no template
 * literals) — this file runs unmodified on arbitrary third-party customer pages that
 * may have no build step and no modern-JS polyfills. Zero dependencies, no imports.
 *
 * Usage (pasted by the customer, generated by the admin "Embed widgets" page):
 *   <script src="https://<keystone-host>/widget.js"
 *           data-org="<org-id>"
 *           data-widget-id="<widget-public-id>"
 *           async></script>
 *
 * Behavior: injects a fixed-position circular chat bubble (bottom-right). Clicking
 * it lazily creates and toggles an iframe panel pointing at the Keystone embed chat
 * page, passing the widget's org/public id plus the parent page's own origin (so the
 * backend can enforce the allowed_origins allowlist).
 */
(function () {
  "use strict";

  // Guard against double-injection (e.g. the snippet pasted twice, or a customer's
  // page loading it via two different code paths).
  if (window.__keystoneWidgetLoaded) return;
  window.__keystoneWidgetLoaded = true;

  function getOwnScriptTag() {
    if (document.currentScript) return document.currentScript;
    // Fallback for older browsers/edge cases where document.currentScript is
    // unavailable inside an async script: the last matching tag on the page is the
    // best available guess (there should only ever be one).
    var candidates = document.querySelectorAll("script[data-widget-id]");
    if (candidates.length === 0) return null;
    return candidates[candidates.length - 1];
  }

  var scriptEl = getOwnScriptTag();
  if (!scriptEl) return;

  var orgId = scriptEl.getAttribute("data-org");
  var widgetId = scriptEl.getAttribute("data-widget-id");
  if (!orgId || !widgetId) return;

  var baseUrl = scriptEl.getAttribute("data-base-url");
  if (!baseUrl) {
    var src = scriptEl.getAttribute("src") || "";
    var suffixIndex = src.indexOf("/widget.js");
    baseUrl = suffixIndex !== -1 ? src.slice(0, suffixIndex) : "";
  }
  // Strip a trailing slash so path concatenation below never double-slashes.
  baseUrl = baseUrl.replace(/\/$/, "");

  var isOpen = false;
  var panelEl = null;
  var iframeEl = null;
  var bubbleEl = null;

  function buildEmbedUrl() {
    var parentOrigin = window.location.origin;
    return (
      baseUrl +
      "/embed?org=" +
      encodeURIComponent(orgId) +
      "&widget=" +
      encodeURIComponent(widgetId) +
      "&parent=" +
      encodeURIComponent(parentOrigin)
    );
  }

  function createPanel() {
    panelEl = document.createElement("div");
    panelEl.setAttribute("aria-label", "Chat window");
    panelEl.style.position = "fixed";
    panelEl.style.bottom = "88px";
    panelEl.style.right = "20px";
    panelEl.style.width = "380px";
    panelEl.style.maxWidth = "calc(100vw - 32px)";
    panelEl.style.height = "560px";
    panelEl.style.maxHeight = "calc(100vh - 120px)";
    panelEl.style.borderRadius = "12px";
    panelEl.style.boxShadow = "0 12px 32px rgba(0, 0, 0, 0.28)";
    panelEl.style.overflow = "hidden";
    panelEl.style.background = "#ffffff";
    panelEl.style.zIndex = "2147483000";
    panelEl.style.display = "none";

    iframeEl = document.createElement("iframe");
    iframeEl.setAttribute("title", "Chat");
    iframeEl.style.width = "100%";
    iframeEl.style.height = "100%";
    iframeEl.style.border = "0";
    iframeEl.src = buildEmbedUrl();

    panelEl.appendChild(iframeEl);
    document.body.appendChild(panelEl);
  }

  function setBubbleIcon(open) {
    // A plain glyph, not an <svg>, keeps this file dependency-free and tiny; a
    // customer page has no Tailwind/icon-font to rely on.
    bubbleEl.innerHTML = open ? "&#10005;" : "&#128172;";
  }

  function togglePanel() {
    if (!panelEl) createPanel();
    isOpen = !isOpen;
    panelEl.style.display = isOpen ? "block" : "none";
    setBubbleIcon(isOpen);
    bubbleEl.setAttribute("aria-label", isOpen ? "Close chat" : "Open chat");
  }

  function createBubble() {
    bubbleEl = document.createElement("button");
    bubbleEl.setAttribute("type", "button");
    bubbleEl.setAttribute("aria-label", "Open chat");
    bubbleEl.style.position = "fixed";
    bubbleEl.style.bottom = "20px";
    bubbleEl.style.right = "20px";
    bubbleEl.style.width = "56px";
    bubbleEl.style.height = "56px";
    bubbleEl.style.borderRadius = "50%";
    bubbleEl.style.border = "none";
    bubbleEl.style.background = "#3b82f6";
    bubbleEl.style.color = "#ffffff";
    bubbleEl.style.fontSize = "24px";
    bubbleEl.style.lineHeight = "56px";
    bubbleEl.style.textAlign = "center";
    bubbleEl.style.padding = "0";
    bubbleEl.style.cursor = "pointer";
    bubbleEl.style.boxShadow = "0 4px 14px rgba(0, 0, 0, 0.25)";
    bubbleEl.style.zIndex = "2147483000";
    setBubbleIcon(false);

    bubbleEl.onclick = togglePanel;
    document.body.appendChild(bubbleEl);
  }

  function inject() {
    createBubble();
  }

  if (document.body) {
    inject();
  } else {
    document.addEventListener("DOMContentLoaded", inject);
  }
})();
